/// Returns true if `n` is even.
fn is_even(n: u32) -> bool {
    n % 2 == 0
}

/// Execution version of `is_even`.
fn is_even_exec(n: u32) -> bool {
    is_even(n)
}

/// Returns true if there exists at least one even number in `arr`.
fn is_product_even(arr: &Vec<u32>) -> bool {
    arr.iter().any(|&x| is_even_exec(x))
}

